import { test as base } from "../helpers/system-control-browser";
import "dotenv/config";
import { expect, type Page } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";
import { Pool } from "pg";
import { randomUUID } from "node:crypto";
import { encode } from "next-auth/jwt";
import { encryptToken } from "../../src/lib/crypto";
import { requireTestDatabaseUrl } from "../helpers/foundation-db";
import type { QuotaSnapshot } from "../../src/lib/quota-snapshot";

requireTestDatabaseUrl();
const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const test = base.extend<{ owner: { id: string; templates: string[] } }>({
  owner: async ({ context }, runFixture) => {
    const id = randomUUID();
    const templates = [randomUUID(), randomUUID()];
    await pool.query(
      'UPDATE "SystemControl" SET "paidGatingEnabled"=true WHERE key=\'global\'',
    );
    await pool.query(
      `INSERT INTO "User" (id,email,name,"googleId","gmailAuthorized","encryptedRefreshToken","gmailScopes","gmailSendOnlyConsentAt","usageBackfillVersion","usageCutoverAt","preferredRoles") VALUES ($1,$2,'Feature User',$1,true,$3,ARRAY['openid','email','profile','https://www.googleapis.com/auth/gmail.send'],NOW(),1,NOW(),ARRAY['Software Engineer'])`,
      [id, `${id}@example.test`, encryptToken("FAKE-FEATURE-TEST-TOKEN", id)],
    );
    for (const [index, templateId] of templates.entries())
      await pool.query(
        `INSERT INTO "Template" (id,"userId",name,subject,body,"createdAt") VALUES ($1,$2,$3,'Hello {{name}}',$4,NOW()+($5*interval '1 second'))`,
        [
          templateId,
          id,
          `Template ${index + 1}`,
          `Full retained content ${index + 1}`,
          index,
        ],
      );
    for (let i = 0; i < 5; i++)
      await pool.query(
        `INSERT INTO "Contact" (id,"userId",name,email,"jobRole") VALUES ($1,$2,$3,$4,'Software Engineer')`,
        [randomUUID(), id, `Recipient ${i}`, `${i}-${id}@example.test`],
      );
    const salt = "authjs.session-token";
    const token = await encode({
      secret: process.env.AUTH_SECRET!,
      salt,
      token: {
        userId: id,
        sub: id,
        plan: "PAID",
        name: "Feature User",
        email: `${id}@example.test`,
      },
    });
    await context.addCookies([
      {
        name: salt,
        value: token,
        domain: "localhost",
        path: "/",
        httpOnly: true,
        sameSite: "Lax",
      },
    ]);
    try {
      await runFixture({ id, templates });
    } finally {
      await pool.query('DELETE FROM "Campaign" WHERE "userId"=$1', [id]);
      await pool.query('DELETE FROM "User" WHERE id=$1', [id]);
      await pool.query(
        'UPDATE "SystemControl" SET "paidGatingEnabled"=false WHERE key=\'global\'',
      );
    }
  },
});
test.use({ reducedMotion: "reduce" });

async function selectTheme(page: Page, theme: string) {
  await page.getByRole("button", { name: "Choose appearance" }).click();
  await page
    .getByRole("menuitemradio", {
      name: theme === "Light" ? "Lavender Light" : "Nightbloom Dark",
      exact: true,
    })
    .click();
  await expect(page.locator("html")).toHaveAttribute(
    "data-theme",
    theme.toLowerCase(),
  );
}

test.afterAll(async () => {
  await pool.end();
});

// A successful focus refresh confirms that the workspace has hydrated before
// interacting with controls that also appear in streamed server HTML.
async function workspaceReady(page: Page) {
  await expect(async () => {
    await Promise.all([
      page.waitForResponse(
        (response) => new URL(response.url()).pathname === "/api/quota",
        { timeout: 1000 },
      ),
      page.evaluate(() => window.dispatchEvent(new Event("focus"))),
    ]);
  }).toPass({ timeout: 15000 });
}

for (const [label, appearance, theme] of [
  ["Lavender Light", "purple", "light"],
  ["Nightbloom Dark", "purple", "dark"],
  ["Chalk Light", "vercel", "light"],
  ["Obsidian Dark", "vercel", "dark"],
]) {
  test(`Contacts Premium link preserves ${label} on Pricing`, async ({
    page,
    context,
    owner,
  }) => {
    if (appearance === "vercel") {
      await pool.query(
        `UPDATE "User" SET "planOverride"='PAID',"planOverrideStartsAt"=NOW(),"planOverrideReason"='Premium theme fixture' WHERE id=$1`,
        [owner.id],
      );
    }
    await page.goto("/contacts");
    await workspaceReady(page);
    await page.getByRole("button", { name: "Choose appearance" }).click();
    await page.getByRole("menuitemradio", { name: label, exact: true }).click();
    const root = page.locator("html");
    await expect(root).toHaveAttribute("data-appearance", appearance);
    await expect(root).toHaveAttribute("data-theme", theme);
    if (appearance === "vercel") {
      await page.getByRole("button", { name: "Account menu" }).click();
    } else {
      await page
        .getByRole("button", { name: "Choose a CSV file · Premium required" })
        .click();
    }
    const link =
      appearance === "vercel"
        ? page.getByRole("menuitem", { name: "Pricing", exact: true })
        : page
            .getByRole("dialog", { name: "Upgrade to Premium", exact: true })
            .getByRole("link", { name: "View full pricing", exact: true });
    if (appearance === "purple") {
      await expect(link).toHaveAttribute("href", "/pricing");
      await expect(link).not.toHaveAttribute("target", "_blank");
    }
    await link.click();
    await expect(page).toHaveURL(/\/pricing$/);
    await expect(page.getByRole("heading", { level: 1 })).toHaveText(
      "Simple pricing for serious outreach.",
    );
    await expect(page.getByRole("table")).toBeVisible();
    await expect(root).toHaveAttribute("data-appearance", appearance);
    await expect(root).toHaveAttribute("data-theme", theme);
    expect(context.pages()).toHaveLength(1);
    await page.reload();
    await expect(page.getByRole("heading", { level: 1 })).toBeVisible();
    await expect(root).toHaveAttribute("data-appearance", appearance);
    await expect(root).toHaveAttribute("data-theme", theme);
  });
}

async function openRetainedTemplates(page: Page) {
  const summary = page
    .locator("summary")
    .filter({ hasText: "Other saved templates" });
  if (
    !(await summary.evaluate((element) =>
      element.parentElement?.hasAttribute("open"),
    ))
  )
    await summary.click();
}

// Display scenarios use real authenticated plan/billing responses with controlled
// counts. The ledger rebuilds derived counters from evidence on every read, so
// changing UsagePeriod counters directly would not create a valid fixture.
async function mockUsageCounts(
  page: Page,
  counts: Record<"daily" | "monthly", { sent: number; reserved: number }>,
) {
  await page.route("**/api/quota", async (route) => {
    const response = await route.fetch();
    const quota: QuotaSnapshot = await response.json();
    if (quota.mode !== "gated") throw new Error("Expected plan allowances.");
    for (const key of ["daily", "monthly"] as const) {
      if (!quota[key].startsAt) continue;
      const used = counts[key].sent + counts[key].reserved;
      Object.assign(quota[key], counts[key], {
        used,
        remaining: Math.max(0, quota[key].limit - used),
      });
    }
    quota.used = quota.daily.used;
    await route.fulfill({ response, json: quota });
  });
}

for (const scenario of [
  { name: "daily exhaustion", daily: 3, monthly: 3, labels: ["Daily"] },
  { name: "monthly exhaustion", daily: 0, monthly: 15, labels: ["Monthly"] },
  { name: "partial capacity", daily: 1, monthly: 1, labels: ["Daily"] },
  {
    name: "both allowances",
    daily: 3,
    monthly: 15,
    labels: ["Daily", "Monthly"],
  },
]) {
  test(`send-limit popup: ${scenario.name}`, async ({ page, owner }) => {
    await mockUsageCounts(page, {
      daily: { sent: scenario.daily, reserved: 0 },
      monthly: { sent: scenario.monthly, reserved: 0 },
    });
    await page.goto("/compose");
    await workspaceReady(page);
    await page.getByLabel("Choose a template").selectOption(owner.templates[0]);
    await page.getByRole("button", { name: "Select all", exact: true }).click();
    const send = page.getByRole("button", {
      name: "Send to 3 recipients",
      exact: true,
    });
    await send.click();
    const popup = page.getByRole("dialog", {
      name: "Upgrade to Premium",
      exact: true,
    });
    await expect(popup).toBeVisible();
    for (const label of scenario.labels)
      await expect(
        popup.getByText(`${label} allowance`, { exact: true }),
      ).toBeVisible();
    await expect(popup).toContainText("Resets");
    for (const plan of ["FREE", "PAID"] as const) {
      const card = popup.getByRole("article", {
        name: plan === "PAID" ? "Premium plan" : "Free plan",
        exact: true,
      });
      await expect(card.locator("li")).toHaveCount(plan === "PAID" ? 10 : 5);
      await expect(card.locator("[data-upgrade-stat]")).toHaveCount(3);
    }
    await expect(
      popup.getByRole("button", { name: /^Upgrade for / }),
    ).toBeEnabled();
    expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
    expect(
      await popup.evaluate((element) => {
        const rect = element.getBoundingClientRect();
        return (
          rect.left >= 0 &&
          rect.right <= innerWidth &&
          rect.top >= 0 &&
          rect.bottom <= innerHeight
        );
      }),
    ).toBe(true);
    await page.keyboard.press("Escape");
    await expect(popup).not.toBeVisible();
    await expect(send).toBeFocused();
    await expect(page.getByLabel("Choose a template")).toHaveValue(
      owner.templates[0],
    );
    await expect(page.locator('input[type="checkbox"]:checked')).toHaveCount(3);
    await send.click();
    await popup.getByRole("button", { name: "Maybe later" }).click();
    await expect(send).toBeFocused();
    await send.click();
    await page.route("**/api/billing/checkout", (route) =>
      route.fulfill({
        status: 503,
        json: { error: "Checkout unavailable in this fixture." },
      }),
    );
    await popup.getByRole("button", { name: /^Upgrade for / }).click();
    await expect(popup.getByRole("alert")).toHaveText(
      "Checkout unavailable in this fixture.",
    );
  });
}

test("send-limit popup: server rejects stale capacity", async ({
  page,
  owner,
}) => {
  await page.goto("/compose");
  await workspaceReady(page);
  await page.getByLabel("Choose a template").selectOption(owner.templates[0]);
  await page.getByRole("button", { name: "Select all", exact: true }).click();
  // Another tab uses capacity after the browser's last snapshot.
  const evidenceKey = randomUUID();
  await pool.query(
    `INSERT INTO "UsageImportEvidence" (id,"userId","sourceKey","deliveryKey","chargedAt","timestampSource") VALUES ($1,$2,$3,$3,NOW(),'sentAt')`,
    [randomUUID(), owner.id, evidenceKey],
  );
  await page
    .getByRole("button", { name: "Send to 3 recipients", exact: true })
    .click();
  const popup = page.getByRole("dialog", {
    name: "Upgrade to Premium",
    exact: true,
  });
  await expect(popup).toBeVisible();
  await expect(
    popup.getByRole("region", { name: "Daily sending allowance", exact: true }),
  ).toContainText(/2\s*remaining/);
  await expect(popup).toContainText("Resets");
  const campaigns = await pool.query(
    'SELECT id FROM "Campaign" WHERE "userId"=$1',
    [owner.id],
  );
  expect(campaigns.rowCount).toBe(0);
});

test("send-limit dark theme, keyboard containment and Premium feedback", async ({
  page,
  owner,
}) => {
  await page.addInitScript(() =>
    localStorage.setItem("mailloop-theme", "dark"),
  );
  await mockUsageCounts(page, {
    daily: { sent: 20, reserved: 0 },
    monthly: { sent: 20, reserved: 0 },
  });
  await page.goto("/compose");
  await workspaceReady(page);
  await page.getByLabel("Choose a template").selectOption(owner.templates[0]);
  await page.getByRole("button", { name: "Select all", exact: true }).click();
  await page
    .getByRole("button", { name: "Send to 3 recipients", exact: true })
    .click();
  const popup = page.getByRole("dialog", {
    name: "Upgrade to Premium",
    exact: true,
  });
  await expect(popup).toBeVisible();
  const later = popup.getByRole("button", { name: "Maybe later" });
  const close = popup.getByRole("button", { name: "Close upgrade dialog" });
  await expect(close).toBeFocused();
  await page.keyboard.press("Shift+Tab");
  await expect(
    popup.getByRole("link", { name: "View full pricing" }),
  ).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(close).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(
    popup.getByRole("region", { name: "Plan comparison" }),
  ).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(
    popup.getByRole("button", { name: /^Upgrade for / }),
  ).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(later).toBeFocused();
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
  await page.keyboard.press("Escape");
  await pool.query(
    `UPDATE "User" SET "planOverride"='PAID',"planOverrideStartsAt"=NOW()-interval '1 day',"planOverrideReason"='Browser fixture' WHERE id=$1`,
    [owner.id],
  );
  await page.reload();
  await workspaceReady(page);
  await page.getByLabel("Choose a template").selectOption(owner.templates[0]);
  await page.getByRole("button", { name: "Select all", exact: true }).click();
  await page
    .getByRole("button", { name: "Send to 5 recipients", exact: true })
    .click();
  await expect(
    page.getByRole("alert").filter({
      hasText: "This campaign would exceed your daily or monthly allowance",
    }),
  ).toBeVisible();
  await expect(popup).not.toBeVisible();
});

