test("Free locks, UTC meters, template switching and owner-only download", async ({
  page,
  owner,
}) => {
  await page.goto("/compose");
  await workspaceReady(page);
  await expect(page.getByText("0 / 3 selected", { exact: true })).toBeVisible();
  await expect(page.getByLabel("Sending capacity")).toHaveText(
    "3 daily · 15 monthly remaining",
  );
  await expect(page.getByRole("meter")).toHaveCount(0);
  await page.getByRole("button", { name: "Select all", exact: true }).click();
  await expect(page.getByText("3 / 3 selected", { exact: true })).toBeVisible();
  await expect(
    page
      .getByLabel("Choose a template")
      .locator("option", { hasText: "Template 2" }),
  ).toBeEnabled();
  page.on("dialog", (dialog) => dialog.accept());
  await page.goto("/templates");
  await expect(
    page.getByRole("heading", { name: "One template. Every introduction." }),
  ).toBeVisible();
  await expect(
    page.getByRole("article", { name: "Template 1", exact: true }),
  ).toContainText("Full retained content 1");
  await openRetainedTemplates(page);
  await page.getByText("View full template", { exact: true }).nth(0).click();
  await expect(
    page.getByText("Full retained content 2", { exact: true }),
  ).toBeVisible();
  const download = page.waitForEvent("download");
  await page.getByRole("link", { name: "Download JSON" }).first().click();
  expect((await download).suggestedFilename()).toMatch(/^template-.*\.json$/);
  const response = await page.request.get(
    `/api/templates/${owner.templates[1]}/export`,
  );
  expect(await response.json()).toMatchObject({
    body: "Full retained content 2",
  });
  await page.getByRole("button", { name: "Use as Free template" }).click();
  await expect(
    page.getByText("Active for Compose", { exact: true }),
  ).toHaveCount(1);
  await expect(
    page.getByRole("article", { name: "Template 2", exact: true }),
  ).toContainText("Full retained content 2");
  await page.goto("/contacts");
  await expect(
    page.getByRole("button", {
      name: "Premium required: CSV import",
      exact: true,
    }),
  ).toBeVisible();
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
  await page.goto("/settings");
  await expect(
    page.getByRole("button", {
      name: "Follow-up reminder delay · Premium required",
    }),
  ).toBeEnabled();
  await page.goto("/history");
  await page.getByRole("button", { name: "Premium actions" }).click();
  await expect(page.getByRole("tooltip")).toContainText("Premium required");
  await page.getByRole("link", { name: "View Premium plan" }).first().focus();
  await expect(
    page.getByRole("link", { name: "View Premium plan" }).first(),
  ).toBeFocused();
  await page.goto("/pricing");
  await expect(
    page.getByRole("heading", { name: "Simple pricing for serious outreach." }),
  ).toBeVisible();
  await expect(page.getByRole("main")).toContainText(
    "Hosted checkout shows the final quote, currency and taxes before you approve payment.",
  );
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
});

for (const paid of [false, true]) {
  test(`${paid ? "Premium" : "Free"} repeat recipients return from History and Contacts`, async ({
    page,
    owner,
  }) => {
    if (paid)
      await pool.query(
        `UPDATE "User" SET "planOverride"='PAID',"planOverrideStartsAt"=NOW(),"planOverrideReason"='Repeat send fixture' WHERE id=$1`,
        [owner.id],
      );
    const {
      rows: [contact],
    } = await pool.query(
      'UPDATE "Contact" SET "shortlistRemovedAt"=now() WHERE "userId"=$1 AND name=$2 RETURNING id,email',
      [owner.id, "Recipient 0"],
    );
    const campaignId = randomUUID();
    await pool.query(
      'INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,\'COMPLETED\')',
      [campaignId, owner.id, owner.templates[0]],
    );
    await pool.query(
      'INSERT INTO "Send" (id,"campaignId","contactId","recipientEmail","recipientName",status,"deliveryState","sentAt") VALUES ($1,$2,$3,$4,$5,\'SENT\',\'DONE\',now())',
      [randomUUID(), campaignId, contact.id, contact.email, "Recipient 0"],
    );
    await page.goto("/history");
    await workspaceReady(page);
    const add = page.getByRole("button", {
      name: "Add to shortlist",
      exact: true,
    });
    if (paid) {
      await expect(add).toHaveAttribute("aria-disabled", "false");
      await add.hover();
      await expect(page.getByRole("tooltip")).toContainText(
        "Add to shortlist to email this person again.",
      );
      await add.click();
    } else {
      await expect(add).toHaveAttribute("aria-disabled", "false");
      await add.focus();
      await expect(page.getByRole("tooltip")).toContainText(
        "On Free, enter and save this person’s details in Contacts to email them again.",
      );
      await add.press("Tab");
      await expect(
        page.getByRole("link", { name: "View Premium plan" }),
      ).toBeFocused();
      await page.keyboard.press("Escape");
      await expect(page.getByRole("tooltip")).toHaveCount(0);
      await add.click({ force: true });
      const {
        rows: [unchanged],
      } = await pool.query(
        'SELECT "followUpRequestedAt","shortlistRemovedAt" FROM "Contact" WHERE id=$1 AND "userId"=$2',
        [contact.id, owner.id],
      );
      expect(unchanged.followUpRequestedAt).toBeNull();
      expect(unchanged.shortlistRemovedAt).not.toBeNull();
      await page.goto("/contacts");
      await workspaceReady(page);
      const form = page.locator(".contact-form");
      await form.getByLabel("Email", { exact: true }).fill(contact.email);
      await form.getByLabel("Name", { exact: true }).fill("Recipient 0");
      await form
        .getByLabel("Job role", { exact: true })
        .fill("Software Engineer");
      await form
        .getByRole("button", { name: "Save contact", exact: true })
        .click();
      await expect(page.getByTestId("success-toast")).toContainText(
        "Contact saved successfully.",
      );
      await page.goto("/history");
      await workspaceReady(page);
    }
    await expect(
      page.getByRole("button", { name: "In shortlist", exact: true }),
    ).toBeVisible();
    await page.goto("/compose");
    await workspaceReady(page);
    const repeat = page.getByRole("checkbox", { name: /^Recipient 0/ });
    await page.getByRole("button", { name: "Select all", exact: true }).click();
    await expect(repeat).not.toBeChecked();
    // Clear the unsent selection before individually authorizing the follow-up.
    await page
      .getByRole("button", { name: "Clear selection", exact: true })
      .click();
    await repeat.check();
    await expect(repeat).toBeChecked();
    await page
      .getByRole("button", {
        name: "Remove Recipient 0 from shortlist",
        exact: true,
      })
      .click();
    await page
      .getByRole("dialog", {
        name: "Remove Recipient 0 from shortlist?",
        exact: true,
      })
      .getByRole("button", { name: "Remove", exact: true })
      .click();
    await expect(repeat).toHaveCount(0);
    await page.goto("/contacts");
    await workspaceReady(page);
    const contactForm = page.locator(".contact-form");
    await contactForm.getByLabel("Email", { exact: true }).fill(contact.email);
    await contactForm.getByLabel("Name", { exact: true }).fill("Recipient 0");
    await contactForm
      .getByLabel("Job role", { exact: true })
      .fill("Software Engineer");
    await contactForm
      .getByRole("button", { name: "Save contact", exact: true })
      .click();
    const row = page
      .getByRole("list", { name: "Your contacts" })
      .getByRole("listitem")
      .filter({ hasText: contact.email });
    await expect(
      row.getByRole("button", { name: "In shortlist", exact: true }),
    ).toBeDisabled();
    await page.goto("/compose");
    await expect(repeat).toBeEnabled();
    await expect(
      page.getByRole("dialog", { name: "Upgrade to Premium", exact: true }),
    ).toHaveCount(0);
  });
}

test("Free template overview makes the single template readable and editable in both themes", async ({
  page,
  owner,
}, testInfo) => {
  await pool.query('DELETE FROM "Template" WHERE id=$1 AND "userId"=$2', [
    owner.templates[1],
    owner.id,
  ]);
  await pool.query(
    `UPDATE "Template" SET name='First introduction',subject='Exploring {{role}} opportunities at {{company}}',body=$3 WHERE id=$1 AND "userId"=$2`,
    [
      owner.templates[0],
      owner.id,
      "Hi {{name}},\n\nI’m interested in {{role}} opportunities at {{company}}. I’d love to share my experience and learn more about your team.\n\nThanks,\nAnoop",
    ],
  );
  await page.goto("/templates");
  await workspaceReady(page);
  const active = page.getByRole("article", {
    name: "First introduction",
    exact: true,
  });
  await expect(
    active.getByText("Active for Compose", { exact: true }),
  ).toBeVisible();
  await expect(
    active.getByRole("region", { name: "Template message" }),
  ).toContainText("Hi {{name}},");
  await expect(
    active.getByRole("link", { name: "Edit template", exact: true }),
  ).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "Other saved templates" }),
  ).toHaveCount(0);
  await expect(
    page.getByRole("navigation", { name: "Pagination" }),
  ).toHaveCount(0);
  await expect(
    page.getByText("Additional saved templates · Paid required.", {
      exact: false,
    }),
  ).toHaveCount(0);
