  ["vercel", "dark"],
] as const) {
  test(`upgrade modal comparison: ${appearance} ${theme}`, async ({
    page,
    owner,
  }, testInfo) => {
    test.skip(testInfo.project.name !== "desktop", "Own viewport matrix");
    test.setTimeout(180000);
