    await mockUsageCounts(page, {
      daily: { sent: 3, reserved: 0 },
      monthly: { sent: 15, reserved: 0 },
    });
    const initialViewport = page.viewportSize()!;
    for (const reason of ["recipient-limit", "allowance"] as const) {
      await page.setViewportSize(initialViewport);
      await page.goto("/compose");
      await workspaceReady(page);
      // Exercise each palette on Free gates without granting Premium entitlements.
      await page.evaluate(
        ({ appearance, theme }) => {
          document.documentElement.dataset.appearance = appearance;
          document.documentElement.dataset.theme = theme;
        },
        { appearance, theme },
      );
      await page
        .getByLabel("Choose a template")
        .selectOption(owner.templates[0]);
      await page
        .getByRole("button", { name: "Select all", exact: true })
        .click();
      const trigger =
        reason === "recipient-limit"
          ? page.getByRole("checkbox", { name: /^Recipient 3/ })
          : page.getByRole("button", {
              name: "Send to 3 recipients",
              exact: true,
            });
      await trigger.click();
      const dialog = page.locator(
        `[role="dialog"][data-upgrade-reason="${reason}"]`,
      );
      await expect(dialog).toBeVisible();
      const contrast = await dialog.evaluate((element) => {
        const style = getComputedStyle(element);
        const luminance = (color: string) => {
          const hex = color.trim().slice(1);
          const channels = color.trim().startsWith("#")
            ? (hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex)
                .match(/../g)!
                .map((c) => parseInt(c, 16))
            : color
                .match(/[\d.]+/g)!
                .slice(0, 3)
                .map(Number);
          const linear = channels.map((c) => {
            const s = c / 255;
            return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
          });
          return linear[0] * 0.2126 + linear[1] * 0.7152 + linear[2] * 0.0722;
        };
        const ratio = (a: string, b: string) => {
          const x = luminance(a),
            y = luminance(b);
          return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05);
        };
        const button = getComputedStyle(element.querySelector(".upgrade-cta")!);
        const endpoints = button.backgroundImage.match(/rgb\([^)]+\)/g)!;
        const stats = getComputedStyle(
          element.querySelector(
            ".upgrade-card-premium [data-upgrade-stat] dt",
          )!,
        );
        return {
          text: ratio(style.color, style.getPropertyValue("--upgrade-surface")),
          button: endpoints.map((c) => ratio(button.color, c)),
          stats: stats.backgroundImage
            .match(/rgb\([^)]+\)/g)!
            .map((c) => ratio(c, style.getPropertyValue("--upgrade-surface2"))),
        };
      });
      expect(contrast.text).toBeGreaterThanOrEqual(4.5);
      for (const ratio of contrast.button)
        expect(ratio).toBeGreaterThanOrEqual(4.5);
      for (const ratio of contrast.stats)
        expect(ratio).toBeGreaterThanOrEqual(4.5);
      await expect(dialog.locator("[data-localized-price]")).toHaveText("₹299");
      await expect(
        dialog.getByRole("article", { name: "Free plan", exact: true }),
      ).toContainText("₹0");
      await expect(
