      await expect(dialog.locator('[data-highlighted="true"]')).toHaveCount(0);
      const upgradeMessage = dialog.locator('[aria-live="polite"]');
      await expect(upgradeMessage).toContainText(
        reason === "allowance"
          ? "Sending limits reached"
          : "More recipients per campaign with Premium",
      );
      await expect(dialog).not.toContainText("Role editing");
      // A mounted, portaled dialog must repaint without being closed or remounted.
      const originalSurface = await dialog
        .locator("article")
        .first()
        .evaluate((el) => getComputedStyle(el).backgroundImage);
      await page.evaluate(
        ({ theme }) => {
          document.documentElement.dataset.theme =
