test("popup checkout opens Dodo directly and retries with the same attempt", async ({
  page,
  owner,
}) => {
  page.on("dialog", (dialog) => dialog.accept());
  await page.goto("/compose");
  await workspaceReady(page);
  await page.getByLabel("Choose a template").selectOption(owner.templates[0]);
  await page.getByRole("button", { name: "Select all", exact: true }).click();
  await page.getByRole("checkbox", { name: /^Recipient 3/ }).click();
  const popup = page.getByRole("dialog", {
    name: "Upgrade to Premium",
    exact: true,
  });
  const requests: { plan: string; idempotencyKey: string }[] = [];
  let releaseCheckout!: () => void;
  const checkoutHeld = new Promise<void>((resolve) => {
    releaseCheckout = resolve;
  });
  await page.route("**/api/billing/checkout", async (route) => {
    expect(route.request().method()).toBe("POST");
    requests.push(route.request().postDataJSON());
    if (requests.length === 1) {
      await checkoutHeld;
      await route.fulfill({
        status: 503,
        json: { error: "Checkout is temporarily unavailable. Try again." },
      });
    } else
      await route.fulfill({
        json: {
          checkoutUrl:
            "https://test.checkout.dodopayments.com/session/popup-fixture",
        },
      });
  });
  await page.route("https://test.checkout.dodopayments.com/**", (route) =>
    route.fulfill({
      contentType: "text/html",
      body: "<h1>Dodo test checkout</h1>",
    }),
  );
  const upgrade = popup.getByRole("button", {
    name: /^Upgrade for /,
    exact: true,
  });
  await upgrade.click();
  const loading = popup.getByRole("button", { name: "Opening checkout…" });
  await expect(loading).toBeDisabled();
  await expect(loading).toHaveAttribute("aria-busy", "true");
  await loading.evaluate((el) => {
    (el as HTMLButtonElement).click();
    (el as HTMLButtonElement).click();
  });
  await expect.poll(() => requests.length).toBe(1);
  releaseCheckout();
  await expect(popup.getByRole("alert")).toHaveText(
    "Checkout is temporarily unavailable. Try again.",
  );
  await expect(upgrade).toBeEnabled();
  await expect(page).toHaveURL(/\/compose$/);
  await expect(page.locator('input[type="checkbox"]:checked')).toHaveCount(3);
  await upgrade.click();
  await expect(page).toHaveURL(
    "https://test.checkout.dodopayments.com/session/popup-fixture",
  );
  expect(requests).toHaveLength(2);
  expect(requests[0]).toEqual(requests[1]);
  expect(requests[0].plan).toBe("paid_monthly");
  expect(requests[0].idempotencyKey).toMatch(/^[0-9a-f-]{36}$/);
});

