  await panel.getByRole("button", { name: "Update role", exact: true }).click();
  await expect(panel.getByRole("alert")).toContainText("Choose unique roles.");
  await input.fill(" ");
  await save.click();
  await expect(panel.getByRole("alert")).toHaveText("Enter a role name.");
  await input.fill("Renamed Engineer");
  await save.click();
  await expect
    .poll(savedRoles)
    .toEqual(["Renamed Engineer", "Platform Engineer"]);
  await expect(
    panel.getByRole("button", { name: "Research Engineer", exact: true }),
  ).toHaveCount(0);
  await panel
    .getByRole("button", { name: "Edit Renamed Engineer", exact: true })
    .click();
  await input.fill("Canceled draft");
  await input.press("Escape");
  await expect(input).toHaveValue("");
  await expect(
    panel.getByRole("button", { name: "Renamed Engineer", exact: true }),
  ).toBeVisible();
  for (const role of [
    "Replacement one",
    "Replacement two",
    "Replacement three",
  ]) {
    const selectedCustom = panel.getByRole("button", {
      name: /^(Renamed Engineer|Replacement (one|two|three))$/,
      exact: true,
    });
    await selectedCustom.click();
    await expect(selectedCustom).toHaveCount(0);
    await input.fill(role);
    await add.click();
    await expect(
      panel
        .getByRole("group", { name: "Role shortcuts", exact: true })
        .locator("button[aria-pressed]"),
    ).toHaveCount(7);
  }
  await panel
    .getByRole("button", { name: "Replacement three", exact: true })
    .click();
  await input.fill("Retry draft");
  await page.route("**/settings", async (route) => {
    if (route.request().headers()["next-action"]) await route.abort("failed");
    else await route.continue();
  });
  await save.click();
  await expect(panel.getByRole("alert")).toHaveText(
    "Could not save preferences. Try again.",
  );
  await expect(input).toHaveValue("Retry draft");
  await expect(
    panel.getByRole("button", { name: "Platform Engineer", exact: true }),
  ).toBeVisible();
  await page.unroute("**/settings");
  await save.click();
  await expect.poll(savedRoles).toEqual(["Platform Engineer", "Retry draft"]);
  await expect(input).toHaveValue("");
  await page.reload();
  await workspaceReady(page);
  await expect(
    panel.getByRole("button", { name: "Retry draft", exact: true }),
  ).toBeVisible();
  const inputBounds = await input.boundingBox();
  const addBounds = await add.boundingBox();
  expect(inputBounds).not.toBeNull();
  expect(addBounds).not.toBeNull();
  expect(Math.abs(inputBounds!.height - addBounds!.height)).toBeLessThanOrEqual(
    1,
  );
  if (page.viewportSize()!.width <= 600) {
    expect(addBounds!.y).toBeGreaterThan(inputBounds!.y);
    expect(Math.abs(inputBounds!.width - addBounds!.width)).toBeLessThanOrEqual(
      1,
    );
  } else {
    expect(Math.abs(inputBounds!.y - addBounds!.y)).toBeLessThanOrEqual(1);
  }
});

for (const [label, appearance, theme] of [
  ["Lavender Light", "purple", "light"],
  ["Nightbloom Dark", "purple", "dark"],
  ["Chalk Light", "vercel", "light"],
  ["Obsidian Dark", "vercel", "dark"],
] as const) {
  test(`role preferences match ${label} colors and interactions`, async ({
    page,
    owner,
  }, info) => {
    await pool.query(
      `UPDATE "User" SET "preferredRoles"=ARRAY['Research Engineer'],"planOverride"='PAID',"planOverrideStartsAt"=NOW(),"planOverrideReason"='Role theme fixture' WHERE id=$1`,
      [owner.id],
    );
    await page.goto("/settings");
    await workspaceReady(page);
    await page.getByRole("button", { name: "Choose appearance" }).click();
    await page.getByRole("menuitemradio", { name: label, exact: true }).click();
    await expect(page.locator("html")).toHaveAttribute(
      "data-appearance",
      appearance,
    );
    await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
    const panel = page.locator("#outreach");
    const input = panel.getByLabel("Custom role", { exact: true });
    const edit = panel.getByRole("button", {
      name: "Edit Research Engineer",
      exact: true,
    });
    const save = panel.getByRole("button", {
      name: "Save preferences",
      exact: true,
    });
    // Resolve the actual theme tokens in the panel's scope, in the same color
    // space as computed styles; do not hardcode any palette's RGB values.
    const colors = await panel.evaluate((element) => {
      const probe = document.createElement("span");
      element.append(probe);
      const resolved = Object.fromEntries(
        [
          "--settings-text",
          "--settings-inset",
          "--input-boundary",
          "--ring",
          "--settings-green",
          "--body",
          "--destructive",
        ].map((token) => {
          probe.style.color = `var(${token})`;
          return [token, getComputedStyle(probe).color];
        }),
      );
      probe.remove();
      return resolved;
    });
    await expect(input).toHaveCSS("color", colors["--settings-text"]);
    await expect(input).toHaveCSS(
      "background-color",
      colors["--settings-inset"],
    );
    await expect(input).toHaveCSS(
      "border-top-color",
      colors["--input-boundary"],
    );
    await expect(edit).toHaveCSS("color", colors["--settings-text"]);
    await expect(panel.locator("#preference-role-help")).toHaveCSS(
      "color",
      colors["--body"],
    );
    // Use keyboard focus so the focus-visible rule is exercised on touch too.
    await input.focus();
    await page.keyboard.press("Shift+Tab");
    await page.keyboard.press("Tab");
    await expect(input).toBeFocused();
    await expect(input).toHaveCSS("outline-style", "solid");
    await expect(input).toHaveCSS("outline-color", colors["--ring"]);
    await input.fill("Platform Engineer");
    await save.click();
    await expect(input).toHaveValue("");
    await expect(panel.getByRole("status")).toHaveText("Saved ✓");
    await expect(panel.getByRole("status")).toHaveCSS(
      "color",
      colors["--settings-green"],
    );
    await edit.click();
    await expect(input).toHaveValue("Research Engineer");
    await expect(
      panel.getByText("Editing Research Engineer", { exact: true }),
    ).toHaveCSS("color", colors["--body"]);
    await input.fill(" platform   engineer ");
    await panel
      .getByRole("button", { name: "Update role", exact: true })
      .click();
    await expect(panel.getByRole("alert")).toContainText(
      "Choose unique roles.",
    );
    await expect(panel.getByRole("alert")).toHaveCSS(
      "color",
      colors["--destructive"],
    );
    expect(
      (await new AxeBuilder({ page }).include("#outreach").analyze())
        .violations,
    ).toEqual([]);
    await panel.screenshot({
      path: info.outputPath(`roles-${appearance}-${theme}-error.png`),
    });
    await input.fill("Renamed Engineer");
    await panel
      .getByRole("button", { name: "Update role", exact: true })
      .click();
    await expect(
      panel.getByRole("button", { name: "Research Engineer", exact: true }),
    ).toHaveCount(0);
    await save.click();
    await expect
      .poll(
        async () =>
          (
            await pool.query(
              'SELECT "preferredRoles" FROM "User" WHERE id=$1',
              [owner.id],
            )
          ).rows[0].preferredRoles,
      )
      .toEqual(["Renamed Engineer", "Platform Engineer"]);
    await page.reload();
    await workspaceReady(page);
    await expect(page.locator("html")).toHaveAttribute(
      "data-appearance",
      appearance,
    );
    await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
    await expect(
      panel.getByRole("button", { name: "Renamed Engineer", exact: true }),
    ).toBeVisible();
    const add = panel.getByRole("button", { name: "Add role", exact: true });
    const inputBounds = (await input.boundingBox())!;
    const addBounds = (await add.boundingBox())!;
    expect(Math.abs(inputBounds.height - addBounds.height)).toBeLessThanOrEqual(
      1,
    );
    if (page.viewportSize()!.width <= 600)
      expect(addBounds.y).toBeGreaterThan(inputBounds.y);
    else expect(Math.abs(inputBounds.y - addBounds.y)).toBeLessThanOrEqual(1);
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth,
      ),
    ).toBe(true);
    await panel.screenshot({
      path: info.outputPath(`roles-${appearance}-${theme}-saved.png`),
    });
  });
}
